    {
      "id": "D1",
      "term": "smooth ES, optimised initials",
      "kind": "method",
      "definition": "smooth 1.2.0 ES(model=<form>, initial='optimal', loss='likelihood', bounds='usual'); smoothing parameters estimated by maximum likelihood with the initial states estimated jointly."
    },
    {
      "id": "D2",
      "term": "smooth ES, backcasting",
      "kind": "method",
      "definition": "smooth 1.2.0 ES(model=<form>, initial='backcasting', loss='likelihood', bounds='usual'): smooth's default; initial states obtained by backcasting, only smoothing parameters optimised."
    },
    {
      "id": "D3",
      "term": "statsforecast AutoETS",
      "kind": "method",
      "definition": "statsforecast 2.1.1 AutoETS(season_length=m, model=<form>, damped=False) with the form fixed to the generating one (no selection); maximum likelihood with optimised initial states; bounds lower 1e-4, upper 0.9999 for alpha, beta, gamma, beta<=alpha, gamma<=1-alpha, and admissibility."
    },
    {
      "id": "D4",
      "term": "ETS data generating process",
      "kind": "data",
      "definition": "Innovations ETS with additive Gaussian errors, sigma=1, started from l0=100, b0=1, s_j=10 sin(2 pi j/12), no burn-in; ETS(A,N,N) alpha 0.1 and 0.5; ETS(A,A,N) (alpha,beta) (0.3,0.05) and (0.5,0.2); ETS(A,N,A) m=12 (alpha,gamma)=(0.2,0.1); lengths 50,100,250,500; R replicates per cell."
    },
    {
      "id": "D5",
      "term": "bias",
      "kind": "variable",
      "definition": "Mean over successful replicates of (estimate minus true value) of a smoothing parameter."
    },
    {
      "id": "D6",
      "term": "RMSE",
      "kind": "variable",
      "definition": "Square root of the mean over successful replicates of the squared (estimate minus true value) of a smoothing parameter."
    },
    {
      "id": "D7",
      "term": "MAE",
      "kind": "variable",
      "definition": "Mean over successful replicates of the absolute value of (estimate minus true value) of a smoothing parameter."
    },
    {
      "id": "D8",
      "term": "consistency",
      "kind": "concept",
      "definition": "The RMSE of an estimator falls towards zero as series length T grows; here assessed on T in {50,100,250,500} by the RMSE at T=500 against the RMSE at T=50 and the trend across the four lengths."
    }
  ],
